"""Declarative base and reusable column types shared by every model."""

import enum
import uuid
from datetime import datetime
from typing import Annotated

from sqlalchemy import CheckConstraint, DateTime, func, text
from sqlalchemy.dialects.postgresql import UUID
from sqlalchemy.orm import DeclarativeBase, mapped_column

# UUID primary key generated by Postgres, so IDs in URLs are not guessable.
UuidPk = Annotated[
    uuid.UUID,
    mapped_column(UUID(as_uuid=True), primary_key=True, server_default=text("gen_random_uuid()")),
]

# Timezone-aware timestamp defaulting to the database clock.
CreatedAt = Annotated[
    datetime,
    mapped_column(DateTime(timezone=True), server_default=func.now()),
]


class Base(DeclarativeBase):
    pass


def status_check(column: str, enum_cls: type[enum.StrEnum], name: str) -> CheckConstraint:
    """CHECK constraint limiting `column` to the values of `enum_cls`.

    Alembic does not autogenerate CHECK constraints, so migrations repeat the values by
    hand: when an enum changes, write a migration that swaps the constraint.
    """
    values = ", ".join(f"'{member.value}'" for member in enum_cls)
    return CheckConstraint(f"{column} IN ({values})", name=name)
